#!/usr/bin/env python3
"""The redesign's copy as CMS pages: one JSON file per page in pages/, on the
existing block types, plus the globals and service copy for launch. Run it
after the copy changes; post the pages with `cms post /pages`."""
import json, os
OUT = os.path.dirname(os.path.abspath(__file__))
SNAP = os.path.join(OUT, "..", "..", "..", "cms", "pages")
TEL = {"kind": "url", "value": "tel:+12695326248"}
PHONE = "(269) 532-6248"
def url(v): return {"kind": "url", "value": v}
def B(t, **d): return {"type": t, "version": 1, "data": d}
def cta(label, link, style="primary"): return {"label": label, "link": url(link) if isinstance(link, str) else link, "style": style}
def hero(eyebrow, heading, lede, ctas=None, items_style="none"):
    return B("page_hero", eyebrow=eyebrow, heading=heading, lede=lede, chips=[], ctas=ctas or [], items_style=items_style, items=[])
def closing(heading="Start with an audit of what you already have.", blurb="A partner reads what you send and builds the audit against your real accounts, not a template. If you'd rather talk it through first, the number below reaches us directly."):
    return B("closing_form", heading=heading, blurb=blurb, phone_kicker="Call us direct", phone_label=PHONE, phone_link=TEL, submit_label="Request my audit", note="")
def faq(eyebrow, heading, qa, tone="bg", body=""):
    return B("faq", eyebrow=eyebrow, heading=heading, items=[{"question": q, "answer": a} for q, a in qa], tone=tone)
def steps(eyebrow, heading, items, columns="3", aside="", note="", tone="bg", anchor=""):
    return B("steps", eyebrow_n="", eyebrow=eyebrow, heading=heading, aside=aside, columns=columns, figures=False, tone=tone, anchor=anchor, items=[{"kicker": k, "title": t, "body": b} for k, t, b in items], note=note)
def cards(eyebrow, heading, items, columns="3", tone="bg", body=""):
    return B("cards", eyebrow_n="", eyebrow=eyebrow, heading=heading, body=body, columns=columns, tone=tone, numbered=False, service_links=False, items=[{"kicker": k, "title": t, "body": b} for k, t, b in items])
def plan(eyebrow, heading, body, items, tone="bg", anchor="", marker="dot", quoted=False):
    return B("numbered_list", eyebrow_n="", eyebrow=eyebrow, heading=heading, body=body, items=[{"title": t, "body": b, "tag": g} for t, b, g in items], tone=tone, heading_size="lg", quoted=quoted, marker=marker, ctas=[], anchor=anchor)
def stats(heading, items): return B("stats_section", heading=heading, body="", image_id="", stats=[{"value": v, "label": l} for v, l in items])
def media(heading, body, image, side="right", bg="accent"): return B("media_text", heading=heading, body=body, image_id=str(image), side=side, background=bg, cta_label="")
def rows(items):
    return B("platforms", eyebrow_n="", eyebrow="", heading="", body="", items=[{"anchor": a, "number": "", "name": "", "role": r, "heading": h, "body": bd, "bullets": bl, "image": str(img), "caption": cap, "flip": flip} for a, r, h, bd, bl, img, cap, flip in items], note_lead="", note="", link_label="")
def casestudies(eyebrow, heading, body, cases, all_=False, link_label="All case studies", tone="subtle", note_lead="", note=""):
    return B("case_studies", eyebrow_n="", eyebrow=eyebrow, heading=heading, body=body, cases=cases, all=all_, link_label=link_label, tone=tone, note_lead=note_lead, note=note)
def audit_form(prefix, heading="Request a marketing audit.", tone="subtle", audit_type="Full system (web + search + ads)"):
    return B("audit_form", eyebrow="The audit", heading=heading, blurb="Tell us where the business is now. For businesses already investing in marketing, or ready to. A partner reads it personally.", bullets=["Read-only access. Nothing changes.", "No slide deck. The findings, with the money attached.", "A partner walks you through it live."], audit_type=audit_type, lock_type=False, submit_label="Request my audit", note="", prefix=prefix, tone=tone)
def live_blocks(slug, types):
    return [b for b in json.load(open(os.path.join(SNAP, slug + ".json")))["page"]["blocks"] if b["type"] in types]

expect_phases = [("Days 1 to 3", "We look", "Read-only access to the accounts and the site. We go through them and write up what we find, with the money attached.", ["Read-only, nothing changes", "You keep the findings, hired or not", "A person walks you through it"]),
                 ("Days 4 to 10", "We set up", "Accounts connected, tracking verified, spend limits and approval rules set with you before anything runs.", ["Your accounts stay in your name", "You set the spend limits", "Tracking checked first"]),
                 ("Day 10 onward", "We run it", "The account gets worked every day. Changes carry their evidence, a named person approves them, and you get one plain-English email a week.", ["Every change explained", "One email each week", "Leads on your phone as they arrive"])]
def engagement(eyebrow, heading): return B("engagement", eyebrow_n="", eyebrow=eyebrow, heading=heading, phases=[{"when": w, "title": t, "body": b, "items": i} for w, t, b, i in expect_phases], answers=[])

