    rows([("integrate", "What we integrate", "The plumbing most agencies skip.", "None of this is glamorous. All of it is the difference between a report that says \"47 conversions\" and a report that says \"11 customers, $42 each, from these three keywords.\"", ["Google Ads and GA4, with conversions verified before they're reported", "Meta Conversions API, server-side, so iOS privacy changes don't blind the account", "ChatGPT ads pixel and Conversions API, deduplicated, running on our own site first", "Call tracking with per-channel numbers and recordings", "Your CRM, booking system or quote tool, so sold-or-lost gets back to the ads", "Google Tag Manager, kept clean, documented, and owned by you"], 8, "The scheduled checks the software runs on an account.", False)]),
    casestudies("What missing tracking costs", "Ten months, $75,000, and nobody counting bookings.", "", "biofuse", link_label=""),
